pub struct Solution;

impl Solution {
    pub fn multiply(num1: String, num2: String) -> String {
        if num1 == "0" || num2 == "0" {
            return "0".to_string();
        }

        let n1 = num1.len();
        let n2 = num2.len();
        let b1 = num1.as_bytes();
        let b2 = num2.as_bytes();

        let mut pos = vec![0u32; n1 + n2];

        for i in (0..n1).rev() {
            for j in (0..n2).rev() {
                let d1 = (b1[i] - b'0') as u32;
                let d2 = (b2[j] - b'0') as u32;
                pos[i + j + 1] += d1 * d2;
            }
        }

        let mut carry = 0;
        for i in (0..pos.len()).rev() {
            let total = pos[i] + carry;
            pos[i] = total % 10;
            carry = total / 10;
        }

        let start = pos.iter().position(|&x| x != 0).unwrap_or(pos.len() - 1);
        pos[start..]
            .iter()
            .map(|&x| (x as u8 + b'0') as char)
            .collect()
    }
}

